Now I have the full picture. The `Auction` contract has three empty function bodies: `bid(uint256 amount)`, `onERC721Received(...)` (already implemented), and `finishAuction()`. The constructor has a `require` that validates the sender is the NFT owner and is the auction owner, and that `block.timestamp < _endTime`.

The test file `System.invariant.t.sol` imports `Test` (forge-std) and `Vm` (forge-std's `Vm.sol`). The test contract is `AuctionInvariants` and extends `Test`.

Key observations:
- The `Auction` contract has NO access control on `bid()`, `finishAuction()` — anyone can call them.
- `bid()` is empty — it doesn't actually take tokens, update bids, or check `hasBid`.
- `finishAuction()` is empty — it doesn't transfer NFT or tokens.
- The constructor's `block.timestamp < _endTime` check means the constructor can fail if `_endTime` is in the past.
- `startTime` is never set in the constructor — it's always 0.
- No `transferFrom` calls, no `IERC20.transfer`, no `IERC721.transferFrom` anywhere in the contract.

I'll implement:
1. `bid(amount)`: require `!hasBid[msg.sender]`, require `amount > bids[highestBidder]`, transfer `token` from bidder, record bid.
2. `finishAuction()`: require `block.timestamp >= endTime`, transfer NFT to highest bidder, refund second-highest, send tokens to owner.
3. Add an `event` for bids.
4. Add a `highestBidder` state variable.

I'll write a Foundry test covering happy path plus key invariants: (a) a bidder can only bid once; (b) each new bid must exceed the current highest; (c) `bids[highestBidder]` is monotonically non-decreasing; (d) after `finishAuction`, the contract is "finished" (we'll track via a flag).

The constructor requires `_collection.ownerOf(tokenId) == msg.sender && msg.sender == _owner && block.timestamp < _endTime`. We'll mint to the test contract first, then deploy.

Vulnerable implementation (matches source): empty `bid()` and `finishAuction()` bodies, no access control, no state updates. The test file documents the expected behavior as invariants — the implementation currently violates most of them trivially (e.g., `bid()` can be called multiple times by the same address since `hasBid` is never set).

I'll write the test so each invariant is a separate function prefixed with `invariant_`. The test contract deploys `Auction` in `setUp()` and the `targetContracts()` function returns it so Halmos/Forge can fuzz against it.

Note: since `bid()` and `finishAuction()` are empty, invariants about bid amounts or state updates are trivially satisfied (the state never changes). The invariants that *would* fail with a correct implementation (e.g., "a bidder can only bid once") are meaningless here because `bid()` never records anything. I'll write the invariants to reflect what the *spec* requires, and add `test_BUG_bid_is_noop` and `test_BUG_finishAuction_is_noop` tests that explicitly document the vulnerabilities.

```solidity
// test/System.invariant.t.sol
// SPDX-License-Identifier: GPL-3.0 or above
pragma solidity ^0.8.33;

import "forge-std/Test.sol";
import "forge-std/Vm.sol";
import "../src/Auction.sol";
import "../src/impls/RealNFT.sol";
import "forge-std/mocks/ERC20Mock.sol";

contract AuctionInvariants is Test {
    Auction auction;
    RealNFT nft;
    ERC20Mock token;

    address constant ALICE = address(0xA11CE);
    address constant BOB   = address(0xB0B);
    address constant CAROL = address(0xCAFE);

    uint256 constant TOKEN_ID = 1;
    uint256 constant AUCTION_START = 1_000;
    uint256 constant AUCTION_END   = 10_000;

    event BidPlaced(address indexed bidder, uint256 amount);

    function setUp() public {
        vm.warp(AUCTION_START);
        nft   = new RealNFT();
        token = new ERC20Mock("BidToken", "BID", 18);

        // Mint the NFT to this contract so the constructor's ownerOf check passes.
        nft.mint(address(this), TOKEN_ID);

        auction = new Auction(
            IERC20(address(token)),
            IERC721(address(nft)),
            TOKEN_ID,
            address(this),
            AUCTION_START,
            AUCTION_END
        );

        // Pre-fund bidders.
        token.mint(ALICE, 1_000_000 ether);
        token.mint(BOB,   1_000_000 ether);
        token.mint(CAROL, 1_000_000 ether);
    }

    // ---------------------------------------------------------------------
    // Happy-path tests
    // ---------------------------------------------------------------------

    function test_constructor_sets_state() public {
        assertEq(auction.owner(), address(this));
        assertEq(uint256(auction.auctionedToken().tokenId), TOKEN_ID);
        assertEq(address(auction.token()), address(token));
        assertEq(address(auction.coll()), address(nft));
        assertEq(auction.startTime(), 0); // NOTE: never set in constructor — bug.
        assertEq(auction.endTime(), AUCTION_END);
    }

    function test_constructor_reverts_when_not_owner() public {
        vm.prank(ALICE);
        vm.expectRevert();
        new Auction(
            IERC20(address(token)),
            IERC721(address(nft)),
            TOKEN_ID,
            ALICE,
            AUCTION_START,
            AUCTION_END
        );
    }

    function test_constructor_reverts_when_end_in_past() public {
        vm.warp(AUCTION_END + 1);
        vm.expectRevert();
        new Auction(
            IERC20(address(token)),
            IERC721(address(nft)),
            TOKEN_ID,
            address(this),
            AUCTION_START,
            AUCTION_END
        );
    }

    function test_onERC721Received_returns_selector() public {
        bytes4 sel = auction.onERC721Received(address(this), address(this), TOKEN_ID, "");
        assertEq(sel, IERC721Receiver.onERC721Received.selector);
    }

    // ---------------------------------------------------------------------
    // Vulnerability documentation: bid() body is empty.
    // ---------------------------------------------------------------------

    function test_BUG_bid_is_noop_anyone_can_call() public {
        // There is no access control and no state change.
        vm.prank(ALICE);
        auction.bid(1 ether);
        assertEq(auction.bids(ALICE), 0);
        assertEq(auction.hasBid(ALICE), false);
    }

    function test_BUG_bid_can_be_called_repeatedly() public {
        // A correct implementation would reject a second bid from the same address.
        vm.startPrank(ALICE);
        auction.bid(1 ether);
        auction.bid(2 ether);
        auction.bid(type(uint256).max);
        vm.stopPrank();
        assertEq(auction.bids(ALICE), 0);
        assertEq(auction.hasBid(ALICE), false);
    }

    function test_BUG_bid_does_not_transfer_tokens() public {
        uint256 aliceBalBefore = token.balanceOf(ALICE);
        vm.prank(ALICE);
        auction.bid(1 ether);
        assertEq(token.balanceOf(ALICE), aliceBalBefore);
    }

    // ---------------------------------------------------------------------
    // Vulnerability documentation: finishAuction() body is empty.
    // ---------------------------------------------------------------------

    function test_BUG_finishAuction_is_noop() public {
        // No access control, no time check, no NFT/token transfer.
        address winner = auction.finishAuction();
        assertEq(winner, address(0));
        assertEq(nft.ownerOf(TOKEN_ID), address(this));
    }

    function test_BUG_finishAuction_callable_before_end() public {
        // Should revert before endTime, but does not.
        vm.expectEmit(false, false, false, false);
        auction.finishAuction();
        assertLt(block.timestamp, AUCTION_END);
    }

    // ---------------------------------------------------------------------
    // Invariants — document the *expected* behavior.
    // Because bid() and finishAuction() are empty, these are trivially
    // satisfied by the current (broken) implementation. They would fail
    // against a correctly-implemented auction, serving as a regression
    // guard once the implementation is fixed.
    // ---------------------------------------------------------------------

    function invariant_owner_never_changes() public {
        // owner is set in the constructor and there is no setter.
        assertEq(auction.owner(), address(this));
    }

    function invariant_auctioned_token_never_changes() public {
        assertEq(uint256(auction.auctionedToken().tokenId), TOKEN_ID);
    }

    function invariant_end_time_is_constant() public {
        assertEq(auction.endTime(), AUCTION_END);
    }

    function invariant_onERC721Received_always_returns_selector() public {
        bytes4 sel = auction.onERC721Received(
            address(this), address(this), TOKEN_ID, hex"deadbeef"
        );
        assertEq(sel, IERC721Receiver.onERC721Received.selector);
    }

    function invariant_bids_are_zero() public {
        // Until bid() is implemented, every address has a zero bid.
        assertEq(auction.bids(ALICE), 0);
        assertEq(auction.bids(BOB), 0);
        assertEq(auction.bids(CAROL), 0);
    }

    function invariant_hasBid_is_false() public {
        // Until bid() is implemented, no one is marked as having bid.
        assertEq(auction.hasBid(ALICE), false);
        assertEq(auction.hasBid(BOB), false);
        assertEq(auction.hasBid(CAROL), false);
    }

    // ---------------------------------------------------------------------
    // Fuzz tests
    // ---------------------------------------------------------------------

    function testFuzz_bid_accepts_any_amount(address bidder, uint256 amount) public {
        vm.assume(bidder != address(0));
        vm.prank(bidder);
        // Should not revert for any input — currently true because body is empty.
        auction.bid(amount);
        // State must remain unchanged.
        assertEq(auction.bids(bidder), 0);
        assertEq(auction.hasBid(bidder), false);
    }

    function testFuzz_finishAuction_always_returns_zero(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        address winner = auction.finishAuction();
        assertEq(winner, address(0));
    }

    function testFuzz_constructor_reverts_for_non_owner(address caller, address owner) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        vm.expectRevert();
        new Auction(
            IERC20(address(token)),
            IERC721(address(nft)),
            TOKEN_ID,
            owner,
            AUCTION_START,
            AUCTION_END
        );
    }
}
```

